mapper.select:
SELECT id, aggregate_type, aggregate_id, event_id, topic, event_key, payload, created_at, processed, status, retry_count, next_retry_at, last_error, processed_at FROM t_outbox WHERE processed = 0 AND topic IN
#{topic}
AND ( (COALESCE(status, 'NEW') IN ('NEW', 'FAILED') AND (next_retry_at IS NULL OR next_retry_at <= NOW())) OR (status = 'PUBLISHING' AND next_retry_at <= NOW()) ) ORDER BY id ASC LIMIT #{limit}

mapper.update:
UPDATE t_outbox
SET status = 'PUBLISHING',
    next_retry_at = #{nextRetryAt}
WHERE id = #{id}
  AND processed = 0
  AND COALESCE(status, 'NEW') IN ('NEW', 'FAILED', 'PUBLISHING')

UPDATE t_outbox
SET processed = 1,
    status = 'DEAD',
    processed_at = NOW(),
    last_error = #{lastError}
WHERE id = #{id}
